arguments.command:
python3 -c "
import json
with open('/app/resources/treasury_bulletin_2016_12.json') as f:
    data = json.load(f)

# Print keys
def print_structure(d, indent=0):
    if isinstance(d, dict):
        for k, v in d.items():
            print(' ' * indent + str(k))
            if isinstance(v, dict) and indent < 2:
                print_structure(v, indent+2)
            elif isinstance(v, list) and indent < 2 and len(v) > 0:
                print(' ' * (indent+2) + f'[{len(v)} items]')

print_structure(data)
"

